export interface Limiter {
  take(key: string): boolean
}

export function createLimiter(max: number): Limiter {
  const seen = new Map<string, number>()
  return {
    take(key) {
      const n = (seen.get(key) ?? 0) + 1
      seen.set(key, n)
      return n <= max
    }
  }
}

export const DEFAULT_MAX = 5
EOF
